   288→// filterToUncommittedFiles removes files from the list that are already committed to HEAD
   289→// with matching content. This prevents re-adding files that an agent committed mid-turn
   290→// (already condensed by PostCommit) back to FilesTouched via SaveStep. Files not in
   291→// HEAD or with different content in the working tree are kept. Fails open: if any git
   292→// operation errors, returns the original list unchanged.
   293→func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
   294→	if len(files) == 0 {
   295→		return files
   296→	}
   297→
   298→	repo, err := openRepository(ctx)
   299→	if err != nil {
   300→		return files // fail open
   301→	}
   302→
   303→	head, err := repo.Head()
   304→	if err != nil {
   305→		return files // fail open (empty repo, detached HEAD, etc.)
   306→	}
   307→
   308→	commit, err := repo.CommitObject(head.Hash())
   309→	if err != nil {
   310→		return files // fail open
   311→	}
   312→
   313→	headTree, err := commit.Tree()
   314→	if err != nil {
   315→		return files // fail open
   316→	}
   317→
   318→	var result []string
   319→	for _, relPath := range files {
   320→		headFile, err := headTree.File(relPath)
   321→		if err != nil {
   322→			// File not in HEAD — it's uncommitted
   323→			result = append(result, relPath)
   324→			continue
   325→		}
   326→
   327→		// File is in HEAD — compare content with working tree
   328→		absPath := filepath.Join(repoRoot, relPath)
   329→		workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
   330→		if err != nil {
   331→			// Can't read working tree file (deleted?) — keep it
   332→			result = append(result, relPath)
   333→			continue
   334→		}
   335→
   336→		headContent, err := headFile.Contents()
   337→		if err != nil {
   338→			result = append(result, relPath)
   339→			continue
   340→		}
   341→
   342→		// Normalize CRLF→LF for text files before comparing: on Windows, agents
   343→		// (Node.js) may write files with CRLF, but git stores blobs with LF after
   344→		// autocrlf normalization. A raw byte comparison would falsely treat the file
   345→		// as uncommitted. Binary files (containing null bytes) are left unchanged.
   346→		workingStr := string(workingContent)
   347→		headStr := headContent
   348→		if !strings.Contains(workingStr, "\x00") {
   349→			workingStr = strings.ReplaceAll(workingStr, "\r\n", "\n")
   350→			headStr = strings.ReplaceAll(headStr, "\r\n", "\n")
   351→		}
   352→		if workingStr != headStr {
   353→			// Working tree differs from HEAD — uncommitted changes
   354→			result = append(result, relPath)
   355→		}
   356→		// else: content matches HEAD — already committed, skip
   357→	}
   358→
   359→	return result
   360→}
   361→
   362→// FilterAndNormalizePaths converts absolute paths to relative and filters out
   363→// infrastructure paths and paths outside the repo.
   364→func FilterAndNormalizePaths(files []string, cwd string) []string {
   365→	var result []string
   366→	for _, file := range files {
   367→		relPath := paths.ToRelativePath(file, cwd)
   368→		if relPath == "" {
   369→			continue // outside repo
   370→		}
   371→		if paths.IsInfrastructurePath(relPath) {
   372→			continue // skip .entire directory
   373→		}
   374→		result = append(result, filepath.ToSlash(relPath))
   375→	}
   376→	return result
   377→}
   378→
   379→// mergeUnique appends elements from extra into base, skipping duplicates already in base.
   380→func mergeUnique(base, extra []string) []string {
   381→	if len(extra) == 0 {
   382→		return base
   383→	}
   384→	seen := make(map[string]bool, len(base))
   385→	for _, s := range base {
   386→		seen[s] = true
   387→	}
   388→	for _, s := range extra {
   389→		if !seen[s] {
   390→			seen[s] = true
   391→			base = append(base, s)
   392→		}
   393→	}
   394→	return base
   395→}
   396→
   397→// resolveTmpDir returns the absolute path to the .entire/tmp directory,
   398→// falling back to a relative path if the repo root can't be determined.
   399→func resolveTmpDir(ctx context.Context) string {
   400→	abs, err := paths.AbsPath(ctx, paths.EntireTmpDir)
   401→	if err != nil {
   402→		return paths.EntireTmpDir
   403→	}
   404→	return abs
   405→}
   406→
   407→// getUntrackedFilesForState returns a list of untracked files using go-git
   408→// Excludes .entire directory
   409→func getUntrackedFilesForState(ctx context.Context) ([]string, error) {
   410→	repo, err := openRepository(ctx)
   411→	if err != nil {
   412→		return nil, err
   413→	}
   414→
   415→	worktree, err := repo.Worktree()
   416→	if err != nil {
   417→		return nil, err //nolint:wrapcheck // already present in codebase
   418→	}
   419→
   420→	status, err := worktree.Status()
   421→	if err != nil {
   422→		return nil, err //nolint:wrapcheck // already present in codebase
   423→	}
   424→
   425→	untrackedFiles := []string{}
   426→	for file, st := range status {
   427→		if st.Worktree == git.Untracked {
   428→			// Exclude .entire directory
   429→			if !paths.IsInfrastructurePath(file) {
   430→				untrackedFiles = append(untrackedFiles, file)
   431→			}
   432→		}
   433→	}
   434→
   435→	return untrackedFiles, nil
   436→}
   437→
   438→// PreTaskState stores the state captured before a task execution
   439→type PreTaskState struct {
   440→	ToolUseID      string   `json:"tool_use_id"`
   441→	Timestamp      string   `json:"timestamp"`
   442→	UntrackedFiles []string `json:"untracked_files"`
   443→}
   444→
   445→// PreUntrackedFiles returns the untracked files list, or nil if the receiver is nil.
   446→// See PrePromptState.PreUntrackedFiles for nil-vs-empty semantics.
   447→func (s *PreTaskState) PreUntrackedFiles() []string {
   448→	if s == nil {
   449→		return nil
   450→	}
   451→	if s.UntrackedFiles == nil {
   452→		return []string{}
   453→	}
   454→	return s.UntrackedFiles
   455→}
   456→
   457→// CapturePreTaskState captures current untracked files before a Task execution
   458→// and saves them to a state file.
   459→// Works correctly from any subdirectory within the repository.
   460→func CapturePreTaskState(ctx context.Context, toolUseID string) error {
   461→	if toolUseID == "" {
   462→		return errors.New("tool_use_id is required")
   463→	}
   464→
   465→	if err := validation.ValidateToolUseID(toolUseID); err != nil {
   466→		return fmt.Errorf("invalid tool use ID for pre-task state: %w", err)
   467→	}
   468→
   469→	// Get absolute path for tmp directory
   470→	tmpDirAbs := resolveTmpDir(ctx)
   471→
   472→	// Create tmp directory if it doesn't exist
   473→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
   474→		return fmt.Errorf("failed to create tmp directory: %w", err)
   475→	}
   476→
   477→	// Get list of untracked files (excluding .entire directory itself)
   478→	untrackedFiles, err := getUntrackedFilesForState(ctx)
   479→	if err != nil {
   480→		return fmt.Errorf("failed to get untracked files: %w", err)
   481→	}
   482→
   483→	// Create state file using os.Root for traversal-resistant write
   484→	state := PreTaskState{
   485→		ToolUseID:      toolUseID,
   486→		Timestamp:      time.Now().UTC().Format(time.RFC3339),
   487→		UntrackedFiles: untrackedFiles,
   488→	}
   489→
   490→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
   491→	if err != nil {
   492→		return fmt.Errorf("failed to marshal state: %w", err)
   493→	}
   494→
   495→	fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
   496→	root, err := os.OpenRoot(tmpDirAbs)
   497→	if err != nil {
   498→		return fmt.Errorf("failed to open tmp directory root: %w", err)
   499→	}
   500→	defer root.Close()
