   502→	if err := osroot.WriteFile(root, fileName, data, 0o600); err != nil {
   503→		return fmt.Errorf("failed to write state file: %w", err)
   504→	}
   505→
   506→	logging.Debug(logging.WithComponent(ctx, "state"), "captured state before task",
   507→		slog.Int("untracked_files", len(untrackedFiles)))
   508→	return nil
   509→}
   510→
   511→// LoadPreTaskState loads previously captured task state.
   512→// Returns nil if no state file exists.
   513→func LoadPreTaskState(ctx context.Context, toolUseID string) (*PreTaskState, error) {
   514→	if err := validation.ValidateToolUseID(toolUseID); err != nil {
   515→		return nil, fmt.Errorf("invalid tool use ID for pre-task state: %w", err)
   516→	}
   517→
   518→	tmpDirAbs := resolveTmpDir(ctx)
   519→
   520→	root, err := os.OpenRoot(tmpDirAbs)
   521→	if err != nil {
   522→		if os.IsNotExist(err) {
   523→			return nil, nil //nolint:nilnil // already present in codebase
   524→		}
   525→		return nil, fmt.Errorf("failed to open tmp directory root: %w", err)
   526→	}
   527→	defer root.Close()
   528→
   529→	fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
   530→	data, err := osroot.ReadFile(root, fileName)
   531→	if err != nil {
   532→		if os.IsNotExist(err) {
   533→			return nil, nil //nolint:nilnil // already present in codebase
   534→		}
   535→		return nil, fmt.Errorf("failed to read state file: %w", err)
   536→	}
   537→
   538→	var state PreTaskState
   539→	if err := json.Unmarshal(data, &state); err != nil {
   540→		return nil, fmt.Errorf("failed to unmarshal state: %w", err)
   541→	}
   542→
   543→	return &state, nil
   544→}
   545→
   546→// CleanupPreTaskState removes the task state file after use
   547→func CleanupPreTaskState(ctx context.Context, toolUseID string) error {
   548→	if err := validation.ValidateToolUseID(toolUseID); err != nil {
   549→		return fmt.Errorf("invalid tool use ID for pre-task state cleanup: %w", err)
   550→	}
   551→
   552→	tmpDirAbs := resolveTmpDir(ctx)
   553→
   554→	root, err := os.OpenRoot(tmpDirAbs)
   555→	if err != nil {
   556→		if os.IsNotExist(err) {
   557→			return nil // Directory doesn't exist, nothing to clean up
   558→		}
   559→		return fmt.Errorf("failed to open tmp directory root: %w", err)
   560→	}
   561→	defer root.Close()
   562→
   563→	fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
   564→	return osroot.Remove(root, fileName) //nolint:wrapcheck // best-effort cleanup, caller adds context via wrapping function name
   565→}
   566→
   567→// preTaskFilePrefix is the prefix for pre-task state files
   568→const preTaskFilePrefix = "pre-task-"
   569→
   570→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
   571→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
   572→// When multiple pre-task files exist (nested subagents), returns the most recently
   573→// modified one.
   574→// Works correctly from any subdirectory within the repository.
   575→func FindActivePreTaskFile(ctx context.Context) (taskToolUseID string, found bool) {
   576→	tmpDirAbs := resolveTmpDir(ctx)
   577→	entries, err := os.ReadDir(tmpDirAbs)
   578→	if err != nil {
   579→		return "", false
   580→	}
   581→
   582→	var latestFile string
   583→	var latestTime time.Time
   584→
   585→	for _, entry := range entries {
   586→		if entry.IsDir() {
   587→			continue
   588→		}
   589→		name := entry.Name()
   590→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
   591→			continue
   592→		}
   593→
   594→		// Check modification time for nested subagent handling
   595→		info, err := entry.Info()
   596→		if err != nil {
   597→			continue
   598→		}
   599→		if latestFile == "" || info.ModTime().After(latestTime) {
   600→			latestFile = name
   601→			latestTime = info.ModTime()
   602→		}
   603→	}
   604→
   605→	if latestFile == "" {
   606→		return "", false
   607→	}
   608→
   609→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
   610→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
   611→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
   612→	return toolUseID, true
   613→}
   614→
   615→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
   616→// It counts existing checkpoint files in the task metadata checkpoints directory.
   617→// Returns 1 if no checkpoints exist yet.
   618→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
   619→	// Use the session ID directly as the metadata directory name
   620→	sessionMetadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
   621→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
   622→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
   623→
   624→	entries, err := os.ReadDir(checkpointsDir)
   625→	if err != nil {
   626→		// Directory doesn't exist or can't be read - start at 1
   627→		return 1
   628→	}
   629→
   630→	// Count JSON files (checkpoints)
   631→	count := 0
   632→	for _, entry := range entries {
   633→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
   634→			count++
   635→		}
   636→	}
   637→
   638→	return count + 1
   639→}
