	if err := os.WriteFile(trackedFile1, []byte("content1"), 0o644); err != nil {
		t.Fatalf("failed to write tracked1: %v", err)
	}
	if err := os.WriteFile(trackedFile2, []byte("content2"), 0o644); err != nil {
		t.Fatalf("failed to write tracked2: %v", err)
	}

