	// Verify it ends with the expected relative path suffix
	expectedSuffix := filepath.Join(paths.EntireTmpDir, "pre-task-toolu_abc123.json")
	got := preTaskStateFile(context.Background(), toolUseID)
	if !filepath.IsAbs(got) {
